// Group the protected-inventory-route authentication scenario.
describe('Swag Labs route protection', () => {
  // Define the single unauthenticated direct-access scenario.
  it('redirects unauthenticated inventory access to the login page', () => {
    // Visit the inventory route directly and allow the response to be handled by the app.
    cy.visit('/inventory.html', { failOnStatusCode: false });

    // Confirm the browser was redirected to the login page.
    cy.location('pathname').should('eq', '/');
    // Confirm the login error is visible and explains that authentication is required.
    cy.get('[data-test="error"]').should('be.visible').and('contain', "Epic sadface: You can only access '/inventory.html' when you are logged in.");
  });
});
